@@ -64,7 +64,7 @@ func NewFromRequest(req *http.Request, count int) *Pages {
 }

 // parseInt parses a string into an integer. If parsing is failed, defaultValue will be returned.
 func parseInt(value string, defaultValue int) int {
-	if value == "" {
+	if value == "" || value[0] == '-' {
 		return defaultValue
 	}
 	if result, err := strconv.Atoi(value); err == nil {
 		return result
 	}
 	return defaultValue
 }
diff --git a/pkg/pagination/pages_test.go b/pkg/pagination/pages_test.go
--- a/pkg/pagination/pages_test.go
+++ b/pkg/pagination/pages_test.go
@@ -82,6 +82,7 @@ func Test_parseInt(t *testing.T) {
 		{"t1", args{"123", 100}, 123},
 		{"t2", args{"", 100}, 100},
 		{"t3", args{"a", 100}, 100},
+		{"t4", args{"-1", 100}, 100},
 	}
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			if got := parseInt(tt.args.value, tt.args.defaultValue); got != tt.want {
 				t.Errorf("parseInt() = %v, want %v", got, tt.want)
 			}
 		})
 	}
 }

 func TestNewFromRequest(t *testing.T) {
 	req, _ := http.NewRequest("GET", "http://example.com?page=2&per_page=20", bytes.NewBufferString(""))
 	p := NewFromRequest(req, 100)
 	assert.Equal(t, 2, p.Page)
 	assert.Equal(t, 20, p.PerPage)
 	assert.Equal(t, 100, p.TotalCount)
 	assert.Equal(t, 5, p.PageCount)
 }
+
+func TestNewFromRequest_InvalidPage(t *testing.T) {
+	req, _ := http.NewRequest("GET", "http://example.com?page=-1", bytes.NewBufferString(""))
+	p := NewFromRequest(req, 100)
+	assert.Equal(t, 1, p.Page)
+	assert.Equal(t, DefaultPageSize, p.PerPage)
+}
+
+func TestNewFromRequest_InvalidLimit(t *testing.T) {
+	req, _ := http.NewRequest("GET", "http://example.com?per_page=-1", bytes.NewBufferString(""))
+	p := NewFromRequest(req, 100)
+	assert.Equal(t, 1, p.Page)
+	assert.Equal(t, DefaultPageSize, p.PerPage)
+}
+
+func TestNewFromRequest_NonNumeric(t *testing.T) {
+	req, _ := http.NewRequest("GET", "http://example.com?page=abc&per_page=xyz", bytes.NewBufferString(""))
+	p := NewFromRequest(req, 100)
+	assert.Equal(t, 1, p.Page)
+	assert.Equal(t, DefaultPageSize, p.PerPage)
+}
+
+func TestNewFromRequest_Overflow(t *testing.T) {
+	req, _ := http.NewRequest("GET", "http://example.com?page=999999999999999999999999", bytes.NewBufferString(""))
+	p := NewFromRequest(req, 100)
+	assert.Equal(t, 1, p.Page)
+	assert.Equal(t, DefaultPageSize, p.PerPage)
+}
+
+func TestNewFromRequest_ValidInput(t *testing.T) {
+	req, _ := http.NewRequest("GET", "http://example.com?page=2&per_page=20", bytes.NewBufferString(""))
+	p := NewFromRequest(req, 100)
+	assert.Equal(t, 2, p.Page)
+	assert.Equal(t, 20, p.PerPage)
+	assert.Equal(t, 100, p.TotalCount)
+	assert.Equal(t, 5, p.PageCount)
+}
```",
